return ['domain'=>'zinn-translate','plural-forms'=>'nplurals=4; plural=((((n >= 2 && n <= 4)) && ((0 == 0))) ? 1 : ((((0 == 0)) == 0)) ? 2 : (((n == 1)) && ((0 == 0))) ? 0 : 3);','language'=>'cs_CZ','project-id-version'=>'zinn-translate','pot-creation-date'=>'2026-10-01T19:55:52+00:00','po-revision-date'=>'2026-10-01T19:55:52+00:00','x-generator'=>'scripts/wp-i18n-translate.py','messages'=>['Zinn® Translate'=>'Zinn® Translate','https://zinndigital.com/wordpress-plugins/zinn-translate'=>'https://zinndigital.com/wordpress-plugins/zinn-translate','Publishes this site in every language you choose, on its own web addresses, with translated slugs, metadata, menus, WooCommerce products, hreflang, per-language sitemaps and llms.txt. Translate with your Zinn Digital® plan or with your own provider key.'=>'Publikuje tento web v každém jazyce, který si vyberete, na vlastních webových adresách, s přeloženými trvalými odkazy (slugs), metadaty, nabídkami, produkty WooCommerce, hreflang, soubory sitemap pro jednotlivé jazyky a llms.txt. Překládejte pomocí svého tarifu Zinn Digital® nebo s vlastním klíčem poskytovatele.','Neil Lock — CEO, Zinn Digital® Ltd'=>'Neil Lock — CEO, Zinn Digital® Ltd','https://zinndigital.com'=>'https://zinndigital.com','Stored. Type a new value to replace it.'=>'Uloženo. Chcete-li hodnotu nahradit, zadejte novou.','Filter this list…'=>'Filtrovat tento seznam…','Filter this list'=>'Filtrovat tento seznam','Nothing matches that filter.'=>'Tomuto filtru nic neodpovídá.','Add a row'=>'Přidat řádek','Remove this row'=>'Odstranit tento řádek','Remove'=>'Odstranit','Zinn Digital®'=>'Zinn Digital®','Zinn Digital® — overview'=>'Zinn Digital® — přehled','Overview'=>'Přehled','Copied'=>'Zkopírováno','Every Zinn® plugin on this site, and whether it is working.'=>'Každý plugin Zinn® na tomto webu a zda funguje.','No connection is needed for this plugin.'=>'Pro tento plugin není vyžadováno žádné připojení.','Open settings'=>'Otevřít nastavení','You do not have permission to change these settings.'=>'Nemáte oprávnění měnit tato nastavení.','Settings sections'=>'Sekce nastavení','Support'=>'Podpora','Save changes'=>'Uložit změny','Tools'=>'Nástroje','Export settings'=>'Exportovat nastavení','Reset to defaults'=>'Obnovit výchozí','This puts every setting on this plugin back to its default. Continue?'=>'Tímto obnovíte všechna nastavení tohoto pluginu na výchozí hodnoty. Chcete pokračovat?','Diagnostics for support'=>'Diagnostika pro podporu','Import a settings file'=>'Importovat soubor s nastavením','Import'=>'Importovat','Exported files never contain passwords, tokens or API keys — you will need to enter those again on the new site.'=>'Exportované soubory nikdy neobsahují hesla, tokeny ani klíče API — na novém webu je budete muset zadat znovu.','Settings saved.'=>'Nastavení bylo uloženo.','Every setting on this plugin is back to its default.'=>'Všechna nastavení tohoto pluginu byla vrácena do výchozího stavu.','Done.'=>'Hotovo.','That action is not available.'=>'Tato akce není k dispozici.','That file could not be read. Choose a settings file exported from a Zinn® plugin.'=>'Tento soubor se nepodařilo přečíst. Vyberte soubor s nastavením exportovaný z pluginu Zinn®.','That file is too large to be a settings export.'=>'Tento soubor je příliš velký na to, aby byl exportem nastavení.','That file is not a Zinn® settings export.'=>'Tento soubor není exportem nastavení Zinn®.','That file was exported from a different plugin (%s), so importing it here would store settings this plugin does not understand.'=>'Tento soubor byl exportován z jiného pluginu (%s), takže jeho importem by se uložila nastavení, kterým tento plugin nerozumí.','%d setting imported. Passwords and API keys are never in an export, so enter those again.'=>'%d nastavení bylo importováno. Hesla a klíče API se do exportu nikdy neukládají, zadejte je proto znovu.' . "\0" . 'Bylo importováno %d nastavení. Hesla a klíče API se do exportu nikdy nezahrnují, proto je prosím zadejte znovu.' . "\0" . 'Bylo importováno %d nastavení. Hesla a klíče API se do exportu nikdy nezahrnují, proto je prosím zadejte znovu.' . "\0" . 'Bylo importováno %d nastavení. Hesla a klíče API se do exportu nikdy nezahrnují, proto je prosím zadejte znovu.','Translate'=>'Přeložit','Manual overrides'=>'Ruční přepsání','Sitemaps and URLs'=>'Soubory sitemap a adresy URL','General'=>'Obecné','Who pays for the translation'=>'Kdo platí za překlad','Either your Zinn Digital® plan, or an API key of your own. There is no free tier — somebody pays a provider for every word.'=>'Buď Váš tarif Zinn Digital®, nebo Váš vlastní klíč API. Neexistuje žádný bezplatný tarif — za každé slovo někdo poskytovateli platí.','My Zinn Digital® plan'=>'Můj tarif Zinn Digital®','My own provider key'=>'Můj vlastní klíč poskytovatele','Site ID'=>'ID webu','From your Zinn Digital® dashboard, on this site\'s Translation tab.'=>'Z vaší nástěnky Zinn Digital®, na záložce Translation tohoto webu.','Site token'=>'Token webu','An API key from your Zinn Digital® dashboard, on its API keys page. Give it the sites.view and sites.translation.manage permissions.'=>'Klíč API z vaší nástěnky Zinn Digital®, na její stránce klíčů API. Udělte mu oprávnění sites.view a sites.translation.manage.','Provider'=>'Poskytovatel','API key'=>'Klíč API','Your key, billed to you by the provider. It is stored on this site and sent only to them.'=>'Váš klíč, účtovaný poskytovatelem. Je uložen na tomto webu a odesílán pouze jemu.','Model'=>'Model','Leave empty for the cheapest model that does the job well.'=>'Ponechte prázdné pro nejlevnější model, který odvede dobrou práci.','This site is written in'=>'Tento web je napsán v jazyce','Leave empty to use the site language from WordPress settings.'=>'Ponechte prázdné, pokud chcete použít jazyk webu z nastavení WordPressu.','Languages to publish'=>'Jazyky k publikování','Each one gets its own web addresses and its own sitemap. Publish only the languages you want indexed.'=>'Každý z nich získá své vlastní webové adresy a vlastní soubor sitemap. Publikujte pouze ty jazyky, které si přejete indexovat.','Translate automatically when I publish or update'=>'Překládat automaticky při publikování nebo aktualizaci','Editing a page marks its translations out of date and they are remade in the background. Editing without changing any words costs nothing.'=>'Úprava stránky označí její překlady jako zastaralé a na pozadí dojde k jejich opětovnému vytvoření. Úprava beze změny slov nic nestojí.','What gets translated'=>'Co se překládá','Post types'=>'Typy příspěvků','Translate the web addresses too'=>'Přeložte také webové adresy','French visitors get /fr/a-propos/ rather than /fr/about/. The untranslated address keeps working and redirects, so nothing that was indexed breaks.'=>'Francouzští návštěvníci získají /fr/a-propos/ namísto /fr/about/. Nepřeložená adresa nadále funguje a přesměrovává, takže se nic z indexovaného obsahu nerozbije.','Translate SEO titles, descriptions and image alt text'=>'Překládejte SEO názvy, popisy a alternativní texty obrázků','Translate categories and tags'=>'Přeložit rubriky a štítky','Translate navigation menus'=>'Přeložit navigační menu','Translate WooCommerce products and attributes'=>'Překládejte produkty a vlastnosti WooCommerce','Short descriptions, purchase notes, attribute labels and variation descriptions. Prices, SKUs and stored option values are never touched.'=>'Stručné popisy, nákupní poznámky, štítky vlastností a popisy variant. Ceny, SKU a uložené hodnoty možností zůstanou zcela nedotčeny.','SEO'=>'SEO','Add hreflang tags'=>'Přidat značky hreflang','Tells search engines these pages are the same page in different languages. Leave this on unless another plugin is already doing it.'=>'Informuje vyhledávače, že tyto stránky jsou stejnou stránkou v různých jazycích. Ponechte tuto možnost zapnutou, pokud to již nedělá jiný plugin.','Publish a sitemap for each language'=>'Publikujte soubor sitemap pro každý jazyk','Publish llms.txt for each language'=>'Publikovat llms.txt pro každý jazyk','A plain-text map of the site that AI answer engines read. They often cannot run JavaScript and may never fetch a sitemap.'=>'Prostá textová mapa webu, kterou čtou vyhledávače s umělou inteligencí. Často neumí spouštět JavaScript a mapu webu nemusí nikdy načíst.','Language switcher'=>'Přepínač jazyků','Style'=>'Styl','Colours, spacing and corners are on the Styling tab. Place it with the block, the [zinn_language_switcher] shortcode, or a menu.'=>'Barvy, mezery a rohy se nacházejí na kartě Stylování. Umístěte jej pomocí bloku, zkráceného kódu [zinn_language_switcher] nebo nabídky.','Show only these languages'=>'Zobrazit pouze tyto jazyky','Leave empty to show every language you publish.'=>'Ponechte prázdné, pokud chcete zobrazit všechny jazyky, ve kterých publikujete.','Name each language in its own language'=>'Pojmenujte každý jazyk v jeho vlastním jazyce','Deutsch rather than German. Somebody who cannot read the current page cannot read "German" either.'=>'Deutsch namísto German. Někdo, kdo neumí přečíst aktuální stránku, nedokáže přečíst ani „German“.','Show flags'=>'Zobrazit vlajky','Off by default: a language is not a country, and Arabic and Spanish have no single flag that does not exclude most of their speakers.'=>'Ve výchozím nastavení vypnuto: jazyk není země a arabština ani španělština nemají žádnou jedinou vlajku, která by nevylučovala většinu jejich mluvčích.','Include the language being read'=>'Zahrnout čtený jazyk','Include the original language'=>'Zahrnout původní jazyk','Add it to this menu'=>'Přidejte to do této nabídky','Only the menu you name here. Nothing is added to any other menu on the site.'=>'Pouze menu, které zde pojmenujete. Do žádného jiného menu na webu se nic nepřidá.','Accent'=>'Zvýraznění','Background'=>'Pozadí','Text'=>'Text','Corner radius'=>'Poloměr zaoblení','Spacing'=>'Mezery','Text size'=>'Velikost textu','Do not add it to a menu'=>'Nepřidávejte do menu','none'=>'žádné','On a Zinn Digital® plan you choose the languages to publish on this site\'s Translation tab in your dashboard, under "Shown to visitors". This site checks it every hour. Publishing now: %s.'=>'V tarifu Zinn Digital® vybíráte jazyky k publikování na záložce Překlad na nástěnce tohoto webu v části „Shown to visitors“. Tento web to kontroluje každou hodinu. Nyní se publikuje: %s.','On a Zinn Digital® plan you choose the languages to publish on this site\'s Translation tab in your dashboard. This site has not read that choice yet, so it is still publishing: %s. Check the Site ID and token above.'=>'V tarifu Zinn Digital® si volíte jazyky k publikování na záložce Překlad pro tento web na své nástěnce. Tento web tuto volbu ještě nenačetl, proto stále publikuje: %s. Zkontrolujte výše uvedené ID webu a token.','Edit any translation here. An edited translation is kept exactly as you wrote it and is never overwritten when the page is translated again.'=>'Zde upravte jakýkoli překlad. Upravený překlad zůstane přesně tak, jak jste jej napsali, a při opětovném překladu stránky nebude nikdy přepsán.','Every language'=>'Všechny jazyky','Search translations'=>'Hledat překlady','Filter'=>'Filtrovat','Content'=>'Obsah','Language'=>'Jazyk','Translation'=>'Překlad','Status'=>'Stav','Save'=>'Uložit','Nothing translated yet. Publish a language and translation starts in the background.'=>'Zatím nebylo nic přeloženo. Publikujte jazyk a překlad se spustí na pozadí.','These addresses are live. Open any of them to check it, and submit the sitemap index to Google Search Console.'=>'Tyto adresy jsou aktivní. Otevřete kteroukoli z nich pro její kontrolu a odešlete index souboru Sitemap do Google Search Console.','You are not allowed to edit translations on this site.'=>'Nemáte oprávnění upravovat překlady na tomto webu.','Edited by you — kept'=>'Upraveno vámi – zachováno','Source changed — will be redone'=>'Zdroj byl změněn — bude provedeno znovu','Up to date'=>'Aktuální','Connected'=>'Připojeno','Connecting…'=>'Připojování…','Connected, but something needs attention'=>'Připojeno, ale něco vyžaduje pozornost','Not connected'=>'Nepřipojeno','Running on your own account'=>'Běží na vašem vlastním účtu','We could not check this'=>'Toto se nám nepodařilo zkontrolovat','This plugin did not say why. Send a diagnostics report and we will look.'=>'Tento plugin neuvedl důvod. Pošlete diagnostické hlášení a my se na to podíváme.','Connection status'=>'Stav připojení','Last checked %s ago.'=>'Naposledy zkontrolováno před %s.','(opens in a new tab)'=>'(otevře se na nové záložce)','Send this to Zinn® support'=>'Odešlete toto podpoře Zinn®','This is exactly what will be sent — nothing else, and nothing hidden. Your passwords, tokens and API keys are not in it.'=>'Přesně toto bude odesláno — nic jiného a nic skrytého. Vaše hesla, tokeny a klíče API v tom nejsou obsaženy.','The diagnostics report that will be sent'=>'Diagnostická zpráva, která bude odeslána','Copy to clipboard'=>'Zkopírovat do schránky','Send this report to Zinn® support'=>'Odešlete toto hlášení podpoře Zinn®','We open a support ticket for you and reply by email. If you would rather not send it, copy it above and paste it into a ticket yourself.'=>'Otevřeme pro Vás požadavek na podporu a odpovíme e-mailem. Pokud jej nechcete odeslat, zkopírujte jej výše a vložte jej do požadavku sami.','We could not reach Zinn Digital® from this server (%s). Copy the report above and open a ticket instead — nothing about your settings is wrong.'=>'Z tohoto serveru (%s) se nepodařilo kontaktovat Zinn Digital®. Zkopírujte výše uvedené hlášení a místo toho otevřete požadavek — ve vašem nastavení není žádná chyba.','Sent. Zinn® support has your report and will reply by email.'=>'Odesláno. Podpora Zinn® obdržela Vaše hlášení a odpoví Vám e-mailem.','Sent. Zinn® support has your report — reference %s — and will reply by email.'=>'Odesláno. Podpora Zinn® obdržela Vaše hlášení — reference %s — a odpoví Vám e-mailem.','You have sent several reports in a short time. Wait a few minutes and try again — the earlier ones did arrive.'=>'Během krátké doby jste odeslali několik hlášení. Počkejte několik minut a zkuste to znovu — předchozí v pořádku dorazila.','Zinn Digital® could not accept the report just now — that is our end, not yours. Try again shortly, or copy the report above into a ticket.'=>'Zinn Digital® právě nemohl zprávu přijmout — chyba je na naší straně, nikoli na Vaší. Zkuste to prosím za chvíli znovu, nebo zkopírujte výše uvedenou zprávu do tiketu.','The report was refused (HTTP %d). Copy it above and open a ticket, quoting that number.'=>'Zpráva byla odmítnuta (HTTP %d). Zkopírujte ji výše a otevřete požadavek na podporu s uvedením tohoto čísla.','%s — guides and services'=>'%s — návody a služby','User guides'=>'Uživatelské příručky','Read the %s user guide'=>'Přečtěte si uživatelskou příručku pro %s','Hide this'=>'Skrýt toto','Zinn® hosting for WordPress'=>'Zinn® hosting pro WordPress','LiteSpeed, daily backups, free migration and a control panel built for people who run more than one site.'=>'LiteSpeed, denní zálohy, bezplatná migrace a ovládací panel vytvořený pro lidi, kteří spravují více než jeden web.','The Zinn® marketplace'=>'Tržiště Zinn®','Buy and sell established sites, domains and link placements, with the money held safely until both sides are happy.'=>'Kupujte a prodávejte zavedené weby, domény a umístění odkazů s tím, že peníze jsou bezpečně uloženy, dokud nebudou obě strany spokojené.','Zinn Hub® — hire people who do this for a living'=>'Zinn Hub® — najměte si lidi, kteří se tímto živí','Our global freelance marketplace: browse over 10,000 ready-made services from writers, designers, developers and SEOs, or post a project and let them bid.'=>'Naše globální tržiště na volné noze: procházejte více než 10 000 hotových služeb od textařů, designérů, vývojářů a SEO specialistů, nebo zadejte projekt a nechte je podávat nabídky.','The API key was rejected. Check that it is still valid and has translation access, then save it again.'=>'Klíč API byl odmítnut. Zkontrolujte, zda je stále platný a má přístup k překladům, a poté jej znovu uložte.','The provider refused on billing or quota. Nothing was translated. Check the balance and limits on your account with them.'=>'Poskytovatel požadavek odmítl z důvodu vyúčtování nebo kvóty. Nic nebylo přeloženo. Zkontrolujte zůstatek a limity na svém účtu u poskytovatele.','The translation provider is having a problem at their end. Nothing was translated or charged, and it will try again on the next pass.'=>'U poskytovatele překladů došlo k problému na jeho straně. Nic nebylo přeloženo ani účtováno a pokus se zopakuje při dalším průchodu.','The translation request failed and we could not tell why. Nothing was saved.'=>'Požadavek na překlad selhal a nepodařilo se zjistit proč. Nic nebylo uloženo.','Sitemap index'=>'Index souborů sitemap','%s sitemap'=>'Soubor sitemap %s','LLM content map'=>'Mapa obsahu pro LLM','%s LLM content map'=>'Mapa obsahu LLM pro %s','Languages published'=>'Publikované jazyky','Site language'=>'Jazyk webu','SEO plugin'=>'SEO plugin','No translation provider is set up yet.'=>'Zatím není nastaven žádný poskytovatel překladu.','Paste an API key from your chosen provider, or connect the site to a Zinn Digital® account, and translation starts on the next pass.'=>'Vložte klíč API od vámi vybraného poskytovatele nebo propojte web s účtem Zinn Digital® a překlad začne při dalším průchodu.','Translating with your own %s key.'=>'Překlad pomocí vašeho vlastního klíče %s.','This site is not connected to a Zinn Digital® account, which is fine — your provider bills you directly.'=>'Tento web není propojen s účtem Zinn Digital®, což je v pořádku — váš poskytovatel vám účtuje přímo.','Not connected to Zinn Digital® yet.'=>'Zatím nepřipojeno k Zinn Digital®.','Add this site\'s ID and token from your Zinn Digital® dashboard, or switch to your own provider key to run without an account.'=>'Přidejte ID a token tohoto webu ze své nástěnky Zinn Digital® nebo přepněte na svůj vlastní klíč poskytovatele, chcete-li web provozovat bez účtu.','Connected to Zinn Digital®.'=>'Připojeno k Zinn Digital®.','The translation provider is having a problem.'=>'U poskytovatele překladu došlo k problému.','Translation is paused — your provider needs attention.'=>'Překlad je pozastaven — váš poskytovatel vyžaduje pozornost.','Translation has not been set up yet.'=>'Překlad zatím nebyl nastaven.','Something went wrong at our end.'=>'Na naší straně došlo k chybě.','Check their status page'=>'Zkontrolujte jejich stavovou stránku','Fix this on your account'=>'Opravte to ve svém účtu','Style preset'=>'Předvolba stylu','A starting point. Anything below overrides it.'=>'Výchozí bod. Cokoliv níže jej přepíše.','Use my own colours and sizes'=>'Použijte mé vlastní barvy a velikosti','Leave this off and the preset is used exactly as it is.'=>'Ponechte tuto možnost vypnutou a předvolba bude použita přesně tak, jak je.','Zinn® language switcher'=>'Přepínač jazyků Zinn®','Let visitors read this page in another language.'=>'Umožněte návštěvníkům číst tuto stránku v jiném jazyce.','Title'=>'Název','Use the plugin setting'=>'Použijte nastavení pluginu','Dropdown'=>'Rozbalovací nabídka','Inline list'=>'Řádkový seznam','Pills'=>'Pilulky','Minimal text'=>'Minimální text','Flags and names'=>'Vlajky a názvy','Stacked list'=>'Skládaný seznam','Choose a language'=>'Zvolte jazyk','See the Zinn Digital® release notes.'=>'Podívejte se na poznámky k vydání Zinn Digital®.','The Zinn® update service did not issue a download link for this update. Check that this site can reach the Zinn® platform, then try again.'=>'Aktualizační služba Zinn® neposkytla odkaz ke stažení této aktualizace. Zkontrolujte, zda se tento web může připojit k platformě Zinn®, a zkuste to znovu.','The update could not be downloaded from the Zinn® update service (%s). Try again in a few minutes.'=>'Aktualizaci se nepodařilo stáhnout ze služby aktualizací Zinn® (%s). Zkuste to prosím znovu za několik minut.','The downloaded update failed its integrity check and was not installed.'=>'Stažená aktualizace neprošla kontrolou integrity a nebyla nainstalována.','No DeepL API key is saved, so there is nothing to translate with.'=>'Není uložen žádný klíč API pro DeepL, takže není s čím překládat.','DeepL does not translate into %s. Choose Google Gemini or OpenAI for this language, or connect the site to Zinn Digital®.'=>'DeepL nepřekládá do jazyka %s. Zvolte pro tento jazyk Google Gemini nebo OpenAI, případně web propojte se službou Zinn Digital®.','DeepL could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Ke službě DeepL se nepodařilo připojit. Nic nebylo přeloženo a nebyl vám naúčtován žádný poplatek; pokus se zopakuje při dalším průchodu.','Your DeepL character quota is used up for this period. Translation resumes when it resets, or when you raise the limit on your DeepL account.'=>'Vaše kvóta znaků DeepL byla pro toto období vyčerpána. Překlad bude pokračovat po jejím obnovení nebo po zvýšení limitu ve vašem účtu DeepL.','DeepL answered with something we could not read. Nothing was saved.'=>'Služba DeepL odpověděla něčím, co se nepodařilo přečíst. Nic nebylo uloženo.','No Google Gemini API key is saved, so there is nothing to translate with.'=>'Není uložen žádný klíč k Google Gemini API, takže není pomocí čeho překládat.','Google Gemini could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'Ke službě Google Gemini se nepodařilo připojit. Nic nebylo přeloženo a nebyl vám naúčtován žádný poplatek; pokus se zopakuje při dalším průchodu.','No OpenAI API key is saved, so there is nothing to translate with.'=>'Není uložen žádný klíč OpenAI API, takže není čím překládat.','OpenAI could not be reached. Nothing was translated and nothing was charged; it will try again on the next pass.'=>'K OpenAI se nepodařilo připojit. Nic nebylo přeloženo a nic nebylo účtováno; pokus se zopakuje v dalším průchodu.','This site is not connected to Zinn Digital®, so there is nothing to collect. Add the Site ID and token, or switch to your own provider key.'=>'Tento web není připojen k Zinn Digital®, takže není co shromažďovat. Přidejte ID webu a token, nebo přepněte na svůj vlastní klíč poskytovatele.','This site is not connected to Zinn Digital®.'=>'Tento web není propojen se službou Zinn Digital®.','Zinn Digital® could not be reached. Nothing was sent; it will try again on the next pass.'=>'K Zinn Digital® se nepodařilo připojit. Nic nebylo odesláno; další pokus proběhne při příštím průchodu.','Translation is paused on this site. Check the account is up to date on your Zinn Digital® dashboard.'=>'Překlad je na tomto webu pozastaven. Zkontrolujte na své nástěnce Zinn Digital®, zda je účet aktuální.','Zinn Digital® rejected this site\'s token. It must be an API key with the sites.view and sites.translation.manage permissions — create one on the API keys page of your dashboard.'=>'Zinn Digital® odmítl token tohoto webu. Musí se jednat o klíč API s oprávněními sites.view a sites.translation.manage — vytvořte jej na stránce klíčů API na své nástěnce.','Zinn Digital® could not be reached. Your site keeps serving the translations it already has.'=>'K Zinn Digital® se nebylo možné připojit. Váš web nadále poskytuje překlady, které již má k dispozici.','Zinn Digital® answered with something we could not read. Your site keeps serving the translations it already has.'=>'Služba Zinn Digital® odpověděla něčím, co se nám nepodařilo přečíst. Váš web nadále poskytuje překlady, které již má k dispozici.','Zinn Digital® could not be reached. Your site keeps publishing the languages it already has.'=>'K Zinn Digital® se nepodařilo připojit. Váš web pokračuje v publikování jazyků, které již obsahuje.','Zinn Digital® answered with something we could not read. Your site keeps publishing the languages it already has.'=>'Zinn Digital® odpověděl něčím, co se nám nepodařilo přečíst. Váš web nadále publikuje jazyky, které již má.']];